enum XfamTone { neutral, info, warning, success, danger }

enum XfamActor { customer, staff, system, none }

enum XfamPhase { request, verification, payment, review, transfer, done }

/// Request lifecycle presentation. `wire` is the API value; `icon` is a Lucide name.
enum XfamStatus {
  draft(
    'draft',
    XfamTone.neutral,
    'circle-dashed',
    XfamActor.customer,
    XfamPhase.request,
    terminal: false,
  ),
  submitted(
