  const XfamStatus(
    this.wire,
    this.tone,
    this.icon,
    this.actor,
    this.phase, {
    required this.terminal,
  });

  final String wire;
  final XfamTone tone;
  final String icon;
  final XfamActor actor;
  final XfamPhase phase;
  final bool terminal;

  static XfamStatus? fromWire(String value) {
    for (final status in values) {
      if (status.wire == value) return status;
    }
    return null;
  }
